// Parsear el input de Telegram
const input = ($input.all()[0] && $input.all()[0].json) || {};

let text = '';
let chatId = null;
let callbackQueryId = null;

if (input.message) {
  text = input.message.text || '';
  chatId = input.message.chat && input.message.chat.id;
} else if (input.callback_query) {
  text = input.callback_query.data || '';
  chatId = input.callback_query.message && input.callback_query.message.chat && input.callback_query.message.chat.id;
  callbackQueryId = input.callback_query.id;
}

const textRaw = String(text || '');
const textLower = textRaw.toLowerCase().trim();
let comando = 'desconocido';
const payload = {};

// ======================================================================
// HELPERS (timezone Argentina)
// ======================================================================
function fmtArgentina(d) {
  const parts = new Intl.DateTimeFormat('en-CA', {
    timeZone: 'America/Argentina/Buenos_Aires',
    year: 'numeric', month: '2-digit', day: '2-digit'
  }).formatToParts(d);
  const y = parts.find(p => p.type === 'year').value;
  const m = parts.find(p => p.type === 'month').value;
  const dd = parts.find(p => p.type === 'day').value;
  return `${y}-${m}-${dd}`;
}

function addDays(yyyy_mm_dd, n) {
  const [y, m, d] = yyyy_mm_dd.split('-').map(Number);
  const date = new Date(Date.UTC(y, m - 1, d));
  date.setUTCDate(date.getUTCDate() + n);
  const yy = date.getUTCFullYear();
  const mm = String(date.getUTCMonth() + 1).padStart(2, '0');
  const dd = String(date.getUTCDate()).padStart(2, '0');
  return `${yy}-${mm}-${dd}`;
}

const hoyArgentina = () => fmtArgentina(new Date());

// ======================================================================
// STATIC DATA: leer contexto previo del orquestador
// ======================================================================
function loadContext() {
  try {
    if (!chatId) return;
    const staticData = $getWorkflowStaticData('global');
    const chatIdStr = String(chatId);
    const ctx = staticData['ctx_' + chatIdStr] || {};
    if (!payload.fecha && ctx.fecha) payload.fecha = ctx.fecha;
    if (!payload.rango && ctx.rango) payload.rango = ctx.rango;
  } catch (e) {}
}

function saveContext() {
  try {
    if (!chatId) return;
    const staticData = $getWorkflowStaticData('global');
    const chatIdStr = String(chatId);
    const existing = staticData['ctx_' + chatIdStr] || {};
    staticData['ctx_' + chatIdStr] = {
      fecha: payload.fecha || existing.fecha,
      rango: payload.rango || existing.rango
    };
  } catch (e) {}
}

// ======================================================================
// GATE DE CAPTURA (design § D3/D4, c-27): bit de ruteo propio del
// orquestador. Nunca contiene la respuesta -- eso vive en captura_<chatId>
// dentro de sub-flujo-crear-turno, un staticData DISTINTO e inaccesible
// desde aca (staticData es por-workflow). Se lee y se limpia aca; se
// ESCRIBE desde Code - Sync Captura, que corre despues de cada dispatch a
// Execute Crear Turno.
// ======================================================================
function leerGateCaptura() {
  try {
    if (!chatId) return null;
    const staticData = $getWorkflowStaticData('global');
    const key = 'gate_captura_' + String(chatId);
    const gate = staticData[key];
    if (!gate) return null;
    if (gate.expira_en && Date.now() > gate.expira_en) {
      delete staticData[key];
      return null;
    }
    return gate;
  } catch (e) {
    return null;
  }
}

function limpiarGateCaptura() {
  try {
    if (!chatId) return;
    delete $getWorkflowStaticData('global')['gate_captura_' + String(chatId)];
  } catch (e) {}
}

// ======================================================================
// PRECEDENCIA (design § D4): comando reconocido > gate de captura pendiente
// > shape cascade (HH:MM / 1-20 / DD/MM/AAAA). Un comando reconocido
// SIEMPRE gana y limpia el gate (escape hatch, D4 paso 1): sin esto, un
// usuario que abandona una reserva a mitad de pregunta queda atrapado,
// porque cualquier mensaje suyo se leeria como respuesta a una pregunta
// que ya olvido.
// ======================================================================
const esCallbackReconocido = textRaw === 'cmd:crear' || textRaw.startsWith('cmd:crear:') ||
  textRaw === 'cmd:cancelar' || textRaw.startsWith('cmd:cancelar:') ||
  textRaw === 'cmd:reprogramar' || textRaw.startsWith('cmd:reprogramar:');

const esComandoTexto = textLower.startsWith('/reservar') || textLower === 'reservar' || textLower.includes('quiero un turno') || textLower.includes('sacar turno') || textLower.startsWith('reservar:') || textLower.startsWith('reservar_lista_') ||
  textLower.startsWith('/cancelar') || textLower === 'cancelar' || textLower.includes('dar de baja') || textLower.startsWith('cancelar:') ||
  textLower.startsWith('/reprogramar') || textLower === 'reprogramar' || textLower.includes('cambiar turno') || textLower.includes('mover turno') || textLower.startsWith('reprogramar:');

const comandoReconocido = esCallbackReconocido || esComandoTexto;

if (comandoReconocido) {
  limpiarGateCaptura();

  // ======================================================================
  // 1) Callbacks de botones inline
  // ======================================================================
  if (textRaw === 'cmd:crear' || textRaw.startsWith('cmd:crear:')) {
    comando = 'crear';
    if (textRaw.startsWith('cmd:crear:rango:')) {
      const rangoPart = textRaw.substring('cmd:crear:rango:'.length);
      payload.rango = rangoPart;
      if (rangoPart !== 'exacto') {
        let daysToAdd = 0;
        if (rangoPart === 'inmediato') daysToAdd = 1;
        else if (rangoPart === '2semanas') daysToAdd = 14;
        else if (rangoPart === '1mes') daysToAdd = 28;
        if (daysToAdd > 0) {
          payload.fecha = addDays(hoyArgentina(), daysToAdd);
          saveContext();
        }
      }
    } else if (textRaw.startsWith('cmd:crear:slot:')) {
      // La fecha viaja en el callback: cmd:crear:slot:HH:MM:f:YYYY-MM-DD (stateless)
      const _rest = textRaw.substring('cmd:crear:slot:'.length);
      const _fIdx = _rest.indexOf(':f:');
      if (_fIdx >= 0) {
        payload.slot = _rest.substring(0, _fIdx);
        payload.fecha = _rest.substring(_fIdx + 3);
      } else {
        payload.slot = _rest;
      }
      loadContext();
    } else if (textRaw.startsWith('cmd:crear:fecha:')) {
      payload.fecha = textRaw.substring('cmd:crear:fecha:'.length);
    }
  } else if (textRaw === 'cmd:cancelar' || textRaw.startsWith('cmd:cancelar:')) {
    comando = 'cancelar';
    if (textRaw.startsWith('cmd:cancelar:turno_id:')) {
      payload.turno_id = textRaw.substring('cmd:cancelar:turno_id:'.length);
    }
  } else if (textRaw === 'cmd:reprogramar' || textRaw.startsWith('cmd:reprogramar:')) {
    comando = 'reprogramar';
    if (textRaw.startsWith('cmd:reprogramar:turno_id:')) {
      payload.turno_id = textRaw.substring('cmd:reprogramar:turno_id:'.length);
    }
  }
  // ======================================================================
  // 5) Comandos de texto (slash + lenguaje natural)
  // ======================================================================
  else if (textLower.startsWith('/reservar') || textLower === 'reservar' || textLower.includes('quiero un turno') || textLower.includes('sacar turno') || textLower.startsWith('reservar:') || textLower.startsWith('reservar_lista_')) {
    comando = 'crear';
  } else if (textLower.startsWith('/cancelar') || textLower === 'cancelar' || textLower.includes('dar de baja') || textLower.startsWith('cancelar:')) {
    comando = 'cancelar';
    if (textLower.startsWith('cancelar:')) {
      payload.turno_id = text.split(':')[1];
    }
  } else if (textLower.startsWith('/reprogramar') || textLower === 'reprogramar' || textLower.includes('cambiar turno') || textLower.includes('mover turno') || textLower.startsWith('reprogramar:')) {
    comando = 'reprogramar';
    if (textLower.startsWith('reprogramar:')) {
      payload.turno_id = text.split(':')[1];
    }
  }
} else {
  const gate = leerGateCaptura();
  if (gate) {
    // Paso 2 (design § D4): con el gate pendiente y vigente, se suspende
    // TODA la shape cascade -- un "15" es una respuesta de DNI, no un
    // slot_numero, y un "10:30" no reingresa al flujo de reserva.
    comando = 'crear';
    payload.respuesta_captura = textRaw;
  }
  // ======================================================================
  // Paso 3: shape cascade, sin tocar -- byte-for-byte como antes de c-27.
  // Solo se alcanza con el gate vacio o vencido.
  // ======================================================================
  // 2) Input de hora HH:MM
  else if (/^\d{1,2}:\d{2}$/.test(textRaw.trim())) {
    comando = 'crear';
    payload.slot = textRaw.trim();
    loadContext();
  }
  // 3) Input de número (slot_numero)
  else if (/^\d+$/.test(textRaw.trim())) {
    const num = parseInt(textRaw.trim(), 10);
    if (num >= 1 && num <= 20) {
      comando = 'crear';
      payload.slot_numero = num;
      loadContext();
    }
  }
  // 4) Input de fecha DD/MM/AAAA
  else if (/^(\d{2})\/(\d{2})\/(\d{4})$/.test(textRaw.trim())) {
    comando = 'crear';
    payload.fecha_raw = textRaw.trim();
    // El orquestador SI persiste staticData: validar y convertir a ISO aca
    const _p = textRaw.trim().split('/');
    const _dd = parseInt(_p[0], 10);
    const _mm = parseInt(_p[1], 10) - 1;
    const _yy = parseInt(_p[2], 10);
    const _parsed = new Date(_yy, _mm, _dd);
    if (_parsed.getDate() === _dd && _parsed.getMonth() === _mm && _parsed.getFullYear() === _yy) {
      const _iso = String(_yy) + '-' + String(_mm + 1).padStart(2, '0') + '-' + String(_dd).padStart(2, '0');
      const _todayStr = hoyArgentina();
      const _maxStr = addDays(_todayStr, 90);
      if (_iso >= _todayStr && _iso <= _maxStr) {
        payload.fecha = _iso;
        saveContext();
      }
    }
  }
}

return [{
  json: {
    comando: comando,
    chat_id: chatId,
    callback_query_id: callbackQueryId,
    text: textRaw,
    payload: payload
  }
}];

// Lee el resultado de sub-flujo-crear-turno (Code - Retorno Estado, c-27
// grupo 7) y sincroniza el gate del orquestador (design § D3/D4). El
// chat_id se lee del nodo "Normalizar Comando" -- no del output del
// Execute Workflow -- porque chat_id no sobrevive al salto entre
// workflows (mismo patron que Code - Verificar Slots / Code - Extraer
// Turno ID en el sub-flujo).
let chatId = null;
try {
  chatId = $('Normalizar Comando').first().json.chat_id;
} catch (e) {}

const input = ($input.all()[0] && $input.all()[0].json) || {};
const capturaPendiente = input.captura_pendiente;
const expiraEn = input.expira_en;
let mostrarAyuda = input.mostrar_ayuda;

// Execute Crear Turno tiene onError: "continueRegularOutput": si el
// sub-workflow no devuelve nada (fallo), no hay ninguno de estos 3
// campos -- fail-safe: se muestra ayuda en vez de silencio.
if (capturaPendiente === undefined && expiraEn === undefined && mostrarAyuda === undefined) {
  mostrarAyuda = true;
}

try {
  if (chatId) {
    const staticData = $getWorkflowStaticData('global');
    const key = 'gate_captura_' + String(chatId);
    if (capturaPendiente === true) {
      staticData[key] = { pendiente: true, expira_en: expiraEn || null };
    } else {
      delete staticData[key];
    }
  }
} catch (e) {}

return [{
  json: {
    chat_id: chatId,
    mostrar_ayuda: !!mostrarAyuda
  }
}];
